CREATE TABLE IF NOT EXISTS vp_accounts(id VARCHAR(80) COLLATE utf8mb4_bin PRIMARY KEY,username VARCHAR(150) COLLATE utf8mb4_unicode_ci NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'user',disabled BOOLEAN NOT NULL DEFAULT 0,created_at BIGINT NOT NULL,auth_version INT NOT NULL DEFAULT 1,email VARCHAR(150) COLLATE utf8mb4_unicode_ci NULL UNIQUE,email_verified BOOLEAN NOT NULL DEFAULT 0,totp_secret TEXT NULL,totp_last BIGINT NOT NULL DEFAULT -1,recovery_hashes TEXT NULL,FOREIGN KEY(id) REFERENCES vp_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vp_settings(name VARCHAR(80) COLLATE utf8mb4_bin PRIMARY KEY,value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vp_metadata(id VARCHAR(80) COLLATE utf8mb4_bin PRIMARY KEY,value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vp_web_audit(id BIGINT AUTO_INCREMENT PRIMARY KEY,at BIGINT NOT NULL,actor VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,subject VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,action VARCHAR(100) NOT NULL,detail TEXT NOT NULL,KEY audit_subject(subject,at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vp_limits(id CHAR(64) PRIMARY KEY,attempts INT NOT NULL,expires_at BIGINT NOT NULL,KEY limits_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS vp_email_codes(id CHAR(64) PRIMARY KEY,email VARCHAR(150) NOT NULL,purpose VARCHAR(20) NOT NULL,code_hash CHAR(64) NOT NULL,expires_at BIGINT NOT NULL,last_sent BIGINT NOT NULL,attempts INT NOT NULL DEFAULT 0,used BOOLEAN NOT NULL DEFAULT 0,KEY code_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS vp_sessions(id CHAR(64) PRIMARY KEY,user_id VARCHAR(80) NOT NULL,auth_version INT NOT NULL,csrf CHAR(64) NOT NULL,data TEXT NOT NULL,seen BIGINT NOT NULL,expires_at BIGINT NOT NULL,KEY sessions_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
